--region init
function WorktableConvertChoiceDialog:InitHandler()
    SetButtonAction(self.ClickClose, Bind(self, self.CloseHandler))
    SetButtonAction(self.BtnClose, Bind(self, self.CloseHandler))
    SetButtonAction(self.FontStyleButton, Bind(self, self.BtnOnClickHandler))
    self._executeJumpEvent = Events.AddListener(Constants.EventNames.EXECUTE_JUMP, Bind(self, self.ExecuteJumpEventHandler))
end

function WorktableConvertChoiceDialog:InitData()
    self:InitArgument()
