function WorktableConvertChoiceDialog:InitArgument()
    local parameters = self.controller.Argument.parameters
    if not parameters then return end
    
    local data = checkTable(parameters.data)
    self._goodsId = checkInt(data.gainId)
    self._list = checkTable(data.children)  
end

function WorktableConvertChoiceDialog:InitUI()
    self:RefreshList()
    self:RefreshItem()
end
