--region handler
function WorktableConvertChoiceDialog:CloseHandler()
    UIModule.CloseDialog(self.controller)
end

function WorktableConvertChoiceDialog:BtnOnClickHandler()
    if not self._selectedIndex then
        GameUtils.Toast(localize("请选择材料"))
        return 
    end
    
    Events.Broadcast(Constants.EventNames.WORKTABLE_CONVERT_CHOOSE, self._list[self._selectedIndex])
    self:CloseHandler()
end

function WorktableConvertChoiceDialog:OnGetItemByIndex(listView, index)
    local cell = listView:NewListViewItem("Cell")
    local goodsNode = cell.transform:Find("GoodNode")
    local scr = CfUtils.GetLuaScr(goodsNode, "Game.Behaviours.GoodNodeMB")
    if isNotNull(scr) then
        local data = self._list[index + 1]
        local amount = GoodsUtils.GetThingNo(data.costItem)
        local costAmount = checkInt(data.costItemNum)
        local canConvert = amount >= costAmount
        local strFmt = "%s/%s"
        if not canConvert then
            strFmt = "<color=#ff0000>%s</color>/%s"
        end
        local num = string.format(strFmt, amount, costAmount)
        CfUtils.RefeshGoodGo2(goodsNode, data.costItem, num, nil, nil, function()
            if canConvert then
                self._selectedIndex = index + 1
                self:RefreshItem()
            else
                GameUtils.ShowCommonGoodsTipsBoard(goodsNode, data.costItem)
            end
        end)
        scr:SetEnoughState(not canConvert)
    end
    return cell
end

---跳转事件处理
function WorktableConvertChoiceDialog:ExecuteJumpEventHandler()
    UIModule.CloseDialog(self.controller)
end
--endregion handler

--region private
function WorktableConvertChoiceDialog:RefreshList()
    local data = self._list
    if not self.ScrollView.IsListViewInit then
        self.ScrollView:InitGridView(#data, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(self.ScrollView, #data)
    end
end

function WorktableConvertChoiceDialog:RefreshItem()
    if self._selectedIndex then
        CfUtils.SetActive(self.BtnReset, false)
        CfUtils.SetActive(self.GoodNode, true)
        local data = self._list[self._selectedIndex]
        CfUtils.RefeshGoodGo2(self.GoodNode, data.costItem, nil, nil, nil, function ()
            local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(data.costItem)
            GameUtils.ShowCommonTipsBoard(self.GoodNode, goodsVo.name, goodsVo.desc, goodsVo.quality, goodsVo.id)
        end)
    else
        CfUtils.SetActive(self.BtnReset, true)
        CfUtils.SetActive(self.GoodNode, false)
    end
end
--endregion private

return WorktableConvertChoiceDialog